from (
  -- Combine Aggregated Outputs
  -- Write to DataTable
  WITH cm_5_cte AS (
    -- Read Elements From Semantic Model 'ad_spend'
    -- Metric Time Dimension 'spend_date'
    -- Select: ['__ad_spend_eur', 'metric_time__month']
    -- Select: ['__ad_spend_eur', 'metric_time__month']
    -- Aggregate Inputs for Simple Metrics
    -- Compute Metrics via Expressions
    SELECT
      TIMESTAMP_TRUNC(spend_date, month) AS metric_time__month
      , SUM(spend) AS ad_spend_eur
    FROM {{ ref('slv_ad_spend') }} ad_spend_src_10000
    GROUP BY
      metric_time__month
  )

  SELECT
    COALESCE(subq_12.metric_time__month, subq_21.metric_time__month) AS metric_time__month
    , MAX(CAST(subq_12.ad_spend_eur AS FLOAT64) / CAST(NULLIF(subq_12.bookings, 0) AS FLOAT64)) AS cost_per_booking_eur
    , MAX(CAST(subq_21.ad_spend_eur AS FLOAT64) / CAST(NULLIF(subq_21.leads, 0) AS FLOAT64)) AS cost_per_lead_eur
  FROM (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(cm_5_cte.metric_time__month, subq_11.metric_time__month) AS metric_time__month
      , MAX(cm_5_cte.ad_spend_eur) AS ad_spend_eur
      , MAX(subq_11.bookings) AS bookings
    FROM cm_5_cte
    FULL OUTER JOIN (
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(__bookings) AS bookings
      FROM (
        -- Read Elements From Semantic Model 'bookings'
        -- Metric Time Dimension 'booked_date'
        -- Select: ['__bookings', 'metric_time__month']
        -- Select: ['__bookings', 'metric_time__month']
        SELECT
          TIMESTAMP_TRUNC(booked_date, month) AS metric_time__month
          , 1 AS __bookings
        FROM {{ ref('slv_bookings') }} bookings_src_10000
      ) subq_9
      GROUP BY
        metric_time__month
    ) subq_11
    ON
      cm_5_cte.metric_time__month = subq_11.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_12
  FULL OUTER JOIN (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(cm_5_cte.metric_time__month, subq_20.metric_time__month) AS metric_time__month
      , MAX(cm_5_cte.ad_spend_eur) AS ad_spend_eur
      , MAX(subq_20.leads) AS leads
    FROM cm_5_cte
    FULL OUTER JOIN (
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(__leads) AS leads
      FROM (
        -- Read Elements From Semantic Model 'leads'
        -- Metric Time Dimension 'created_date'
        -- Select: ['__leads', 'metric_time__month']
        -- Select: ['__leads', 'metric_time__month']
        SELECT
          TIMESTAMP_TRUNC(created_date, month) AS metric_time__month
          , 1 AS __leads
        FROM {{ ref('slv_leads') }} leads_src_10000
      ) subq_18
      GROUP BY
        metric_time__month
    ) subq_20
    ON
      cm_5_cte.metric_time__month = subq_20.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_21
  ON
    subq_12.metric_time__month = subq_21.metric_time__month
  GROUP BY
    metric_time__month
) as metricflow
